/**
 * Google Analytics (GA4) - Central configuration and tracking utilities.
 * All tracking is no-op when REACT_APP_GA_MEASUREMENT_ID is not set.
 * User and team context from user.utils.js is attached to all events for per-user/team analysis.
 *
 * Setup: Set REACT_APP_GA_MEASUREMENT_ID in .env (e.g. G-XXXXXXXXXX).
 *
 * Page views: Sent automatically on every route change (see App.jsx).
 *
 * Button/event tracking (Option A - preferred): Put these attributes on the element:
 *
 *   data-ga-action="action_name"           (required)
 *   data-ga-category="auth"               (optional, default: "engagement")
 *   data-ga-label="Sign in"               (optional)
 *   data-ga-value="1"                     (optional, numeric)
 *
 * Example: <button data-ga-action="login_submit" data-ga-category="auth" data-ga-label="Sign in">Sign in</button>
 *
 * The global click listener in App.jsx sends the event. No wrapper needed.
 * Alternative: trackEvent() in code or <TrackClick> wrapper (see TrackClick.jsx).
 */

import { userUtils } from './user.utils';

const GA_MEASUREMENT_ID = process.env.REACT_APP_GA_MEASUREMENT_ID;
const isEnabled = () => typeof window !== 'undefined' && GA_MEASUREMENT_ID;

/**
 * Get current user/team context from user.utils for analytics. Safe to call when not logged in.
 * Returns {} if unavailable; use for user_id, team_id, and GA4 user properties.
 */
function getUserContext() {
  if (typeof window === 'undefined') return {};
  try {
    const userId = userUtils.getCurrentUserId && userUtils.getCurrentUserId();
    const teamId = userUtils.getCurrentTeamId && userUtils.getCurrentTeamId();
    const teamName = userUtils.getCurrentTeamName && userUtils.getCurrentTeamName();
    const loginType = userUtils.getLoginType && userUtils.getLoginType();
    const userName = userUtils.getCurrentUserName && userUtils.getCurrentUserName();
    if (userId == null && teamId == null) return {};
    return {
      user_id: userId != null ? String(userId) : undefined,
      team_id: teamId != null ? String(teamId) : undefined,
      team_name: teamName || undefined,
      login_type: loginType || undefined,
      user_name: userName || undefined,
    };
  } catch (e) {
    return {};
  }
}

/**
 * Set GA4 user ID and user properties from current user/team. Call before events when context exists.
 */
function setUserContext() {
  if (!isEnabled()) return;
  const ctx = getUserContext();
  if (ctx.user_id) {
    window.gtag('config', GA_MEASUREMENT_ID, { user_id: ctx.user_id });
  }
  const userProps = {};
  if (ctx.team_id) userProps.team_id = ctx.team_id;
  if (ctx.team_name) userProps.team_name = ctx.team_name;
  if (ctx.login_type) userProps.login_type = ctx.login_type;
  if (ctx.user_name) userProps.user_name = ctx.user_name;
  if (Object.keys(userProps).length) {
    window.gtag('set', 'user_properties', userProps);
  }
}

/**
 * Event params that include user/team for segmentation. Omit undefined values.
 */
function getEventUserParams() {
  const ctx = getUserContext();
  const params = {};
  if (ctx.user_id) params.user_id = ctx.user_id;
  if (ctx.team_id) params.team_id = ctx.team_id;
  if (ctx.team_name) params.team_name = ctx.team_name;
  if (ctx.login_type) params.login_type = ctx.login_type;
  return params;
}

/**
 * Initialize Google Analytics. Loads gtag script and configures the property.
 * Call once when the app mounts (e.g. in App.jsx).
 */
export function init() {
  if (!GA_MEASUREMENT_ID) return;

  window.dataLayer = window.dataLayer || [];
  function gtag() {
    window.dataLayer.push(arguments);
  }
  window.gtag = gtag;
  gtag('js', new Date());

  const script = document.createElement('script');
  script.async = true;
  script.src = `https://www.googletagmanager.com/gtag/js?id=${GA_MEASUREMENT_ID}`;
  document.head.appendChild(script);

  gtag('config', GA_MEASUREMENT_ID, {
    send_page_view: false, // We send page_view manually on route change
  });
}

/**
 * Track a page view (call on every route change).
 * Includes user_id, team_id, team_name, login_type for per-user/team analysis.
 * @param {string} path - Full path (e.g. /project/dashboard)
 * @param {string} [title] - Optional page title
 */
export function trackPageView(path, title) {
  if (!isEnabled()) return;
  setUserContext();
  window.gtag('event', 'page_view', {
    page_path: path || window.location.pathname,
    page_title: title || document.title,
    ...getEventUserParams(),
  });
}

/**
 * Track a custom event (button clicks, feature usage, etc.).
 * Includes user_id, team_id, team_name, login_type for per-user/team analysis.
 * @param {string} action - Action name (e.g. 'click_login', 'submit_form')
 * @param {string} [category] - Category (e.g. 'engagement', 'auth')
 * @param {string} [label] - Optional label for the event
 * @param {number} [value] - Optional numeric value
 */
export function trackEvent(action, category = 'engagement', label = '', value) {
  if (!isEnabled()) return;
  setUserContext();
  const params = {
    event_category: category,
    ...getEventUserParams(),
  };
  if (label) params.event_label = label;
  if (value != null) params.value = value;
  window.gtag('event', action, params);
}

export default {
  init,
  trackPageView,
  trackEvent,
  setUserContext,
  getUserContext,
  isEnabled: () => !!GA_MEASUREMENT_ID,
};
