import React, { useEffect, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import { connect } from "react-redux";
import { withRouter } from "react-router-dom";
import { employeeActions, workItemActions } from "_actions";
import { workItemConstants } from "_constants";
import { accessUtils, commonUtils, store } from "_helpers";
import dateUtils from "_helpers/date.utils";
import workItemUtils from "_helpers/workitem.utils";
import PageInnerHeader from "views/common/PageInnerHeader";
import CreateWorkItemSidebar from "./modal/CreateWorkItemSidebar";

const STATUS_FILTER_OPTIONS = {
  SHOW: {
    options: [
      { name: "ALL", label: "All" },
      { name: "ASSIGNED", label: "Assigned" },
      { name: "INPROGRESS", label: "In Progress" },
      { name: "COMPLETED", label: "Completed" },
      { name: "CLOSED", label: "Closed" },
    ],
    selected: "ALL",
  },
  filterText: "",
};

/** Fixed capacity for utilization math (per product requirement). */
const RESOURCE_PLANNER_DAY_CAPACITY_MINUTES = 8 * 60;

const STATUS_COLORS = {
  ASSIGNED: "rgb(59,130,246)",
  INPROGRESS: "rgb(245,158,11)",
  COMPLETED: "rgb(16,185,129)",
  CLOSED: "rgb(71,85,105)",
  NEW: "rgb(14,165,233)",
  ONGOING: "rgb(139,92,246)",
  PAUSED: "rgb(234,88,12)",
  DEFAULT: "rgb(100,116,139)",
};

/** Work items often use numeric employeeId while directory ids may be strings (or vice versa). */
function employeeIdsMatch(workItemEmployeeId, selectedId) {
  if (workItemEmployeeId == null || selectedId == null) {
    return false;
  }
  const a = Number(workItemEmployeeId);
  const b = Number(selectedId);
  if (!Number.isNaN(a) && !Number.isNaN(b)) {
    return a === b;
  }
  return String(workItemEmployeeId).trim() === String(selectedId).trim();
}

function normalizeWorkItemStatus(status) {
  return String(status || "").trim().toUpperCase();
}

function getWorkItemStatusColor(status) {
  const key = normalizeWorkItemStatus(status);
  return STATUS_COLORS[key] || STATUS_COLORS.DEFAULT;
}

function getItemStartDate(item) {
  const st = normalizeWorkItemStatus(item.status);
  const startValue =
    item.actualStartTime && (st === "COMPLETED" || st === "CLOSED")
      ? item.actualStartTime
      : item.estStartTime || item.estimatedStartTime;
  return startValue ? new Date(startValue) : null;
}

function getItemEndDate(item, startDate) {
  const st = normalizeWorkItemStatus(item.status);
  const endValue =
    item.actualEndTime && (st === "COMPLETED" || st === "CLOSED")
      ? item.actualEndTime
      : item.estCompletionTime || item.estimatedEndTime || item.actualCompletionTime;
  if (endValue) {
    return new Date(endValue);
  }
  const duration = item.estDurationInMins || item.durationInMinutes || 60;
  return new Date(startDate.getTime() + duration * 60 * 1000);
}

function formatHours(minutes) {
  const mins = Math.max(0, Math.round(minutes || 0));
  const hours = Math.floor(mins / 60);
  const rem = mins % 60;
  return `${hours}h ${String(rem).padStart(2, "0")}m`;
}

function getPlannerDays(startMoment, horizonWeeks) {
  const totalDays = Math.max(1, horizonWeeks) * 7;
  return [...Array(totalDays)].map((_, idx) => startMoment.clone().add(idx, "days"));
}

function isPlannerWeekday(dayMoment) {
  const iw = dayMoment.isoWeekday();
  return iw >= 1 && iw <= 5;
}

/** Mon–Fri only; Sat/Sun excluded from utilization math. */
function getPlannerWorkingDaysMoments(startMoment, horizonWeeks) {
  return getPlannerDays(startMoment.clone(), horizonWeeks).filter(isPlannerWeekday);
}

/** Weekdays Mon–Fri in the horizon (ISO weekdays 1–5). Used as billable-capacity days at 8h/day. */
function getPlannerWorkingDayCount(startMoment, horizonWeeks) {
  const count = getPlannerWorkingDaysMoments(startMoment.clone(), horizonWeeks).length;
  return Math.max(count, 1);
}

/** Same roster semantics as Task Planner: do not drop rows when `active` is omitted from API. */
function getPlannerRosterEmployees(employees) {
  const list = employees || [];
  return list.filter((e) => e != null && e.deleted !== true && e.active !== false);
}

function getWorkItemEmployeeId(item) {
  if (!item) {
    return null;
  }
  if (item.employeeId != null && item.employeeId !== "") {
    return item.employeeId;
  }
  if (item.assignedEmployeeId != null && item.assignedEmployeeId !== "") {
    return item.assignedEmployeeId;
  }
  if (item.resourceEmployeeId != null && item.resourceEmployeeId !== "") {
    return item.resourceEmployeeId;
  }
  if (item.employee && item.employee.id != null && item.employee.id !== "") {
    return item.employee.id;
  }
  return null;
}

function resolvePlannerRowKeyAndTitle(item, viewMode) {
  if (viewMode === "WORK_ITEMS") {
    return {
      key: String(item.id),
      title: item.name || item.taskName || item.taskActCategory || "Work item",
    };
  }
  if (viewMode === "PROJECTS") {
    return {
      key: String(item.projectId != null ? item.projectId : item.id),
      title: item.projectName || item.name || "Untitled",
    };
  }
  return {
    key: String(item.taskId != null ? item.taskId : item.id),
    title: item.taskName || item.name || "Untitled",
  };
}

function getOverlappedMinutes(startDate, endDate, dayMoment) {
  if (!startDate || !endDate) {
    return 0;
  }
  const dayStart = dayMoment.clone().startOf("day");
  const dayEnd = dayMoment.clone().endOf("day");
  const itemStart = dateUtils.convertDateToMoment(startDate);
  const itemEnd = dateUtils.convertDateToMoment(endDate);
  const overlappedStart = itemStart.isAfter(dayStart) ? itemStart : dayStart;
  const overlappedEnd = itemEnd.isBefore(dayEnd) ? itemEnd : dayEnd;
  if (overlappedEnd.diff(overlappedStart, "minutes") <= 0) {
    return 0;
  }
  return overlappedEnd.diff(overlappedStart, "minutes");
}

function ResourcePlanner(props) {
  const [permission] = useState(accessUtils.getTaskPlannerAccessControl());
  const [filterOptions, setFilterOptions] = useState(STATUS_FILTER_OPTIONS);
  const [selectedEmployeeId, setSelectedEmployeeId] = useState(commonUtils.getCurrentUserId());
  const [viewMode, setViewMode] = useState("TASKS");
  const [horizonWeeks, setHorizonWeeks] = useState(2);
  const [weekStartMoment, setWeekStartMoment] = useState(dateUtils.getCurrentTime().clone().startOf("isoWeek"));

  const getCurrentRange = (startMoment = weekStartMoment, weeks = horizonWeeks) => ({
    startDateMoment: startMoment.clone(),
    endDateMoment: startMoment.clone().add(weeks * 7 - 1, "days").endOf("day"),
  });

  const getPlannerUserTeamIds = () =>
    commonUtils.getSelectedUserTeamIds(
      commonUtils.getUserTeams(props.userTeamsTaskPlanner || props.userTeams)
    );

  useEffect(() => {
    const userTeams = commonUtils.getUserTeams(props.userTeams);
    store.dispatch({
      type: workItemConstants.INITIALIZE_TASK_PLANNER_USER_TEAMS,
      userTeams,
    });
    reloadEmployees(userTeams);
    reloadPlannerItems(commonUtils.getSelectedUserTeamIds(userTeams), getCurrentRange());
  }, []);

  const reloadEmployees = (userTeams) => {
    const selectedUserTeamIds = commonUtils.getSelectedUserTeamIds(userTeams);
    if (selectedUserTeamIds.length > 0) {
      props.getTeamsEmployees(selectedUserTeamIds);
    }
  };

  /** Loads activities for all employees in scope; filter by selected employee in UI. */
  const reloadPlannerItems = (userTeamIds, range) => {
    const requestObj = {
      employeeIds:[],
      userTeamIds: userTeamIds || [],
      startDate: range.startDateMoment.format(dateUtils.SERVER_DATE_FORMAT),
      endDate: range.endDateMoment.format(dateUtils.SERVER_DATE_FORMAT),
    };
    props.getWorkItemActivities(requestObj);
  };

  const handleUserTeamsSelection = (userTeams) => {
    store.dispatch({
      type: workItemConstants.INITIALIZE_TASK_PLANNER_USER_TEAMS,
      userTeams,
    });
    const userTeamIds = commonUtils.getSelectedUserTeamIds(userTeams);
    reloadEmployees(userTeams);
    reloadPlannerItems(userTeamIds, getCurrentRange());
  };

  const handleEmployeesSelection = (employees) => {
    const employeeIds = commonUtils.getSelectedEmployeeIds(employees);
    const effectiveId =
      employeeIds.length > 0 ? employeeIds[0] : commonUtils.getCurrentUserId();
    setSelectedEmployeeId(effectiveId);
    const cachedItems = props.workItems || [];
    if (cachedItems.length === 0) {
      reloadPlannerItems(getPlannerUserTeamIds(), getCurrentRange());
    }
  };

  const handleFilterChange = (newFilterOptions) => {
    setFilterOptions(newFilterOptions);
  };

  const onFilterTextChange = (value) => {
    setFilterOptions((prevState) => ({
      ...prevState,
      filterText: value,
    }));
  };

  const goToBack = () => {
    const nextStart = weekStartMoment.clone().subtract(horizonWeeks, "week");
    setWeekStartMoment(nextStart);
    reloadPlannerItems(getPlannerUserTeamIds(), getCurrentRange(nextStart));
  };

  const goToNext = () => {
    const nextStart = weekStartMoment.clone().add(horizonWeeks, "week");
    setWeekStartMoment(nextStart);
    reloadPlannerItems(getPlannerUserTeamIds(), getCurrentRange(nextStart));
  };

  const goToCurrent = () => {
    const nextStart = dateUtils.getCurrentTime().clone().startOf("isoWeek");
    setWeekStartMoment(nextStart);
    reloadPlannerItems(getPlannerUserTeamIds(), getCurrentRange(nextStart));
  };

  const plannerData = useMemo(() => {
    const employees = getPlannerRosterEmployees(props.employees || []);
    const selectedEmployee =
      employees.find((employee) => employeeIdsMatch(employee.id, selectedEmployeeId)) || employees[0] || null;
    if (!selectedEmployee) {
      return { selectedEmployee: null, rowsByDay: {}, utilizationByDay: {}, totalAllocated: 0 };
    }

    const sourceItems = props.workItems || [];
    const status = filterOptions.SHOW && filterOptions.SHOW.selected;
    const statusFilter = normalizeWorkItemStatus(status);
    const text = (filterOptions.filterText || "").trim().toLowerCase();
    const weekDays = getPlannerDays(weekStartMoment.clone(), horizonWeeks);

    const filteredItems = sourceItems.filter((item) => {
      const itemStatus = normalizeWorkItemStatus(item.status);
      const matchesStatus = status === "ALL" || itemStatus === statusFilter;
      const haystack = `${item.name || ""} ${item.projectName || ""} ${item.taskName || ""} ${item.taskActCategory || ""}`.toLowerCase();
      const matchesText = text.length < 3 || haystack.includes(text);
      return matchesStatus && matchesText && employeeIdsMatch(getWorkItemEmployeeId(item), selectedEmployee.id);
    });

    const rowsByDay = {};
    const utilizationByDay = {};
    let totalAllocated = 0;

    weekDays.forEach((dayMoment) => {
      const dayKey = dayMoment.format("YYYY-MM-DD");
      const grouped = {};

      filteredItems.forEach((item) => {
        const startDate = getItemStartDate(item);
        if (!startDate) {
          return;
        }
        const endDate = getItemEndDate(item, startDate);
        const overlappedMins = getOverlappedMinutes(startDate, endDate, dayMoment);
        if (overlappedMins <= 0) {
          return;
        }
        const { key, title } = resolvePlannerRowKeyAndTitle(item, viewMode);
        if (!grouped[key]) {
          grouped[key] = {
            id: key,
            name: title,
            projectName: item.projectName,
            taskName: item.taskName,
            minutes: 0,
            items: [],
            statusWeights: {},
          };
        }
        grouped[key].minutes += overlappedMins;
        grouped[key].items.push(item);
        const st = normalizeWorkItemStatus(item.status) || "UNKNOWN";
        grouped[key].statusWeights[st] = (grouped[key].statusWeights[st] || 0) + overlappedMins;
      });

      const rows = Object.values(grouped)
        .map((row) => {
          const ranked = Object.entries(row.statusWeights || {}).sort((left, right) => right[1] - left[1]);
          const dominantStatus = ranked.length > 0 ? ranked[0][0] : "ASSIGNED";
          return {
            ...row,
            dominantStatus,
            bgColor: getWorkItemStatusColor(dominantStatus),
          };
        })
        .sort((left, right) => right.minutes - left.minutes);
      const dayAllocated = rows.reduce((sum, row) => sum + row.minutes, 0);
      if (isPlannerWeekday(dayMoment)) {
        totalAllocated += dayAllocated;
      }
      rowsByDay[dayKey] = rows;
      utilizationByDay[dayKey] = dayAllocated;
    });
    return { selectedEmployee, rowsByDay, utilizationByDay, totalAllocated };
  }, [props.employees, props.workItems, filterOptions, selectedEmployeeId, weekStartMoment, viewMode, horizonWeeks]);

  const plannerWorkingDayCount = getPlannerWorkingDayCount(weekStartMoment, horizonWeeks);
  const weekCapacityMins = RESOURCE_PLANNER_DAY_CAPACITY_MINUTES * plannerWorkingDayCount;
  const weekUtilizationPercent = Math.min(
    100,
    Math.round((plannerData.totalAllocated / Math.max(weekCapacityMins, 1)) * 100)
  );
  const weekFreeMins = Math.max(0, weekCapacityMins - plannerData.totalAllocated);
  const dayUtilizations = Object.entries(plannerData.utilizationByDay || {})
    .filter(([dayKey]) => {
      const m = dateUtils.convertDateStringToMoment(dayKey);
      return m && isPlannerWeekday(m);
    })
    .map(([, mins]) =>
      Math.round((mins / Math.max(RESOURCE_PLANNER_DAY_CAPACITY_MINUTES, 1)) * 100)
    );
  const overbookedDays = dayUtilizations.filter((value) => value > 100).length;
  const underbookedDays = dayUtilizations.filter((value) => value < 60).length;
  const utilizationByResource = useMemo(() => {
    const roster = getPlannerRosterEmployees(props.employees || []);
    const sourceItems = props.workItems || [];
    const workingDays = getPlannerWorkingDaysMoments(weekStartMoment.clone(), horizonWeeks);
    if (!workingDays || workingDays.length === 0) {
      return [];
    }

    const capacity =
      RESOURCE_PLANNER_DAY_CAPACITY_MINUTES *
      getPlannerWorkingDayCount(weekStartMoment.clone(), horizonWeeks);

    const minutesForEmployee = (employeeId) =>
      sourceItems
        .filter((item) => employeeIdsMatch(getWorkItemEmployeeId(item), employeeId))
        .reduce((sum, item) => {
          const itemStart = getItemStartDate(item);
          if (!itemStart) {
            return sum;
          }
          const itemEnd = getItemEndDate(item, itemStart);
          const itemMinutes = workingDays.reduce(
            (daySum, dayMoment) => daySum + getOverlappedMinutes(itemStart, itemEnd, dayMoment),
            0
          );
          return sum + itemMinutes;
        }, 0);

    const rows = roster.map((employee) => {
      const minutes = minutesForEmployee(employee.id);
      const utilization = Math.round((minutes / Math.max(capacity, 1)) * 100);
      return {
        id: employee.id,
        name: employee.name,
        minutes,
        utilization,
        freeMinutes: Math.max(0, capacity - minutes),
      };
    });

    const orphans = [];
    sourceItems.forEach((item) => {
      const wid = getWorkItemEmployeeId(item);
      if (wid == null) {
        return;
      }
      if (roster.some((e) => employeeIdsMatch(e.id, wid))) {
        return;
      }
      if (orphans.some((o) => employeeIdsMatch(o, wid))) {
        return;
      }
      orphans.push(wid);
    });

    orphans.forEach((wid) => {
      const minutes = minutesForEmployee(wid);
      const utilization = Math.round((minutes / Math.max(capacity, 1)) * 100);
      rows.push({
        id: wid,
        name: `Employee ${wid}`,
        minutes,
        utilization,
        freeMinutes: Math.max(0, capacity - minutes),
      });
    });

    rows.sort((left, right) => right.utilization - left.utilization);
    return rows;
  }, [props.employees, props.workItems, weekStartMoment, horizonWeeks]);
  const busyResources = utilizationByResource.filter((item) => item.utilization >= 90).slice(0, 5);
  const availableResources = utilizationByResource
    .filter((item) => item.utilization <= 60)
    .sort((left, right) => left.utilization - right.utilization || right.freeMinutes - left.freeMinutes);
  const resourceRequests = availableResources.map((resource) => ({
    id: String(resource.id),
    title: `Allocate ${resource.name}`,
    description: `${formatHours(resource.freeMinutes)} available in selected horizon`,
    score: Math.max(60, 100 - resource.utilization),
  }));

  const handleCreateItem = () => {
    store.dispatch({ type: workItemConstants.SHOW_TASKPLANNER_CREATE_WINDOW });
  };

  const closeCreateItem = () => {
    store.dispatch({ type: workItemConstants.CLOSE_TASKPLANNER_CREATE_WINDOW });
  };

  const refreshAfterSave = () => {
    reloadPlannerItems(getPlannerUserTeamIds(), getCurrentRange());
  };

  return (
    <div className="resource-planner-page">
      <PageInnerHeader
        userTeams={commonUtils.getUserTeams(props.userTeamsTaskPlanner || props.userTeams)}
        handleUserTeamsSelection={handleUserTeamsSelection}
        showCreateMenu={permission.createEnabled}
        showCreateMenuText="Assign Tasks"
        createItemHandler={handleCreateItem}
        showGridListMenu={false}
        showFilter={true}
        showEmployeeMenu={true}
        employeeMenuEnabled={true}
        employeeEnableSingleSelection={true}
        showEmployeeNameDropDownLabel={true}
        applyEmployeeSelectionImmediately={true}
        employees={props.employees}
        handleEmployeesSelection={handleEmployeesSelection}
        showUserTeamMenu={true}
        isLoading={props.isLoading}
        filterOptions={filterOptions}
        handleFilterChange={handleFilterChange}
        onFilterTextChange={onFilterTextChange}
        showDateRangeSelector={false}
        permission={permission}
        enableCalendarControl={!props.showTaskPlannerCreateModel}
        calendarControls={{
          goToBack,
          goToCurrent,
          goToNext,
        }}
      />

      <div className="card-body pt-3 resource-planner-body">
      

        <div className="resource-planner-insights">
          <div className="resource-planner-panel">
            <h6 className="mb-2">Who is Busy?</h6>
            {busyResources.length === 0 && <div className="text-muted fsize12">No one is over 90% utilization.</div>}
            {busyResources.map((resource) => (
              <div key={resource.id} className="resource-planner-insight-row">
                <span>{resource.name}</span>
                <span className="text-danger">{resource.utilization}%</span>
              </div>
            ))}
          </div>
          <div className="resource-planner-panel">
            <h6 className="mb-2">Who Needs More Work?</h6>
            {availableResources.length === 0 ? (
              <div className="text-muted fsize12">Everyone is at healthy utilization.</div>
            ) : (
              <div className="resource-planner-panel__scroll">
                {availableResources.map((resource) => (
                  <div key={resource.id} className="resource-planner-insight-row">
                    <span>{resource.name}</span>
                    <span className="text-success">{formatHours(resource.freeMinutes)} free</span>
                  </div>
                ))}
              </div>
            )}
          </div>
          <div className="resource-planner-panel">
            <h6 className="mb-2">Resource Requests</h6>
            {resourceRequests.length === 0 ? (
              <div className="text-muted fsize12">No suggestions yet for this horizon.</div>
            ) : (
              <div className="resource-planner-panel__scroll">
                {resourceRequests.map((request) => (
                  <div key={request.id} className="resource-planner-request">
                    <div className="resource-planner-request__head">
                      <span>{request.title}</span>
                      <span className="badge badge-primary">Match {request.score}%</span>
                    </div>
                    <div className="text-muted fsize12">{request.description}</div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="resource-planner-toolbar">
          <div className="resource-planner-horizon">
            <label className="mb-1 d-block text-muted">Planning Horizon</label>
            <div className="btn-group">
              {[1, 2, 4].map((weeks) => (
                <button
                  key={weeks}
                  type="button"
                  className={`btn btn-sm ${horizonWeeks === weeks ? "btn-primary" : "btn-outline-primary"}`}
                  onClick={() => {
                    setHorizonWeeks(weeks);
                    reloadPlannerItems(getPlannerUserTeamIds(), getCurrentRange(weekStartMoment, weeks));
                  }}
                >
                  {weeks}W
                </button>
              ))}
            </div>
          </div>
          <div className="resource-planner-view-mode">
            <label className="mb-1 d-block text-muted">View</label>
            <div className="btn-group flex-wrap">
              <button
                type="button"
                className={`btn btn-sm ${viewMode === "WORK_ITEMS" ? "btn-primary" : "btn-outline-primary"}`}
                onClick={() => setViewMode("WORK_ITEMS")}
              >
                Work items
              </button>
              <button
                type="button"
                className={`btn btn-sm ${viewMode === "TASKS" ? "btn-primary" : "btn-outline-primary"}`}
                onClick={() => setViewMode("TASKS")}
              >
                Tasks
              </button>
              <button
                type="button"
                className={`btn btn-sm ${viewMode === "PROJECTS" ? "btn-primary" : "btn-outline-primary"}`}
                onClick={() => setViewMode("PROJECTS")}
              >
                Projects
              </button>
            </div>
          </div>
          <div className="resource-planner-summary">
            <div className="rp-metric">
              <span className="rp-metric__label">Utilization</span>
              <span className="rp-metric__value">{weekUtilizationPercent}%</span>
            </div>
            <div className="rp-metric">
              <span className="rp-metric__label">Allocated</span>
              <span className="rp-metric__value">{formatHours(plannerData.totalAllocated)}</span>
            </div>
            <div className="rp-metric">
              <span className="rp-metric__label">Free Time</span>
              <span className="rp-metric__value">{formatHours(weekFreeMins)}</span>
            </div>
            <div className="rp-metric">
              <span className="rp-metric__label">Overbooked Days</span>
              <span className="rp-metric__value">{overbookedDays}</span>
            </div>
            <div className="rp-metric">
              <span className="rp-metric__label">Underbooked Days</span>
              <span className="rp-metric__value">{underbookedDays}</span>
            </div>
          </div>
        </div>

        <div className="resource-planner-grid">
          {getPlannerDays(weekStartMoment.clone(), horizonWeeks).map((dayMoment) => {
            const dayKey = dayMoment.format("YYYY-MM-DD");
            const rows = plannerData.rowsByDay[dayKey] || [];
            const allocatedMins = plannerData.utilizationByDay[dayKey] || 0;
            const countsTowardUtilization = isPlannerWeekday(dayMoment);
            const freeMins = countsTowardUtilization
              ? Math.max(0, RESOURCE_PLANNER_DAY_CAPACITY_MINUTES - allocatedMins)
              : null;
            const utilization = countsTowardUtilization
              ? Math.min(
                  100,
                  Math.round((allocatedMins / Math.max(RESOURCE_PLANNER_DAY_CAPACITY_MINUTES, 1)) * 100)
                )
              : null;
            return (
              <div className="resource-planner-day" key={dayKey}>
                <div className="resource-planner-day__header">
                  <div>
                    <strong>{dayMoment.format("ddd")}</strong>
                    <div className="text-muted fsize12">{dayMoment.format("DD MMM YYYY")}</div>
                  </div>
                  <div className="text-right">
                    {countsTowardUtilization ? (
                      <>
                        <div className="fsize12">{utilization}% used</div>
                        <div className="text-muted fsize11">{formatHours(freeMins)} free</div>
                      </>
                    ) : (
                      <div className="text-muted fsize11">Excluded from utilization</div>
                    )}
                  </div>
                </div>
                <div className="resource-planner-day__progress">
                  <div
                    className="resource-planner-day__progress-fill"
                    style={{
                      width: countsTowardUtilization ? `${utilization}%` : "0%",
                      opacity: countsTowardUtilization ? 1 : 0.35,
                    }}
                  />
                </div>
                <div className="resource-planner-day__content">
                  {rows.length === 0 && <div className="text-muted fsize12">No allocation</div>}
                  {rows.map((row) => (
                    <button
                      type="button"
                      className="resource-planner-item"
                      key={`${dayKey}-${row.id}`}
                      style={{
                        borderLeft: `4px solid ${row.bgColor}`,
                      }}
                      onClick={() => {
                        const firstItem = row.items && row.items[0];
                        if (firstItem && firstItem.taskId) {
                          props.history.push(`/project/deliverable/${firstItem.taskId}`);
                        }
                      }}
                    >
                      <span className="resource-planner-item__dot" style={{ backgroundColor: row.bgColor }} />
                      <span className="resource-planner-item__meta">
                        <span className="resource-planner-item__title">{row.name}</span>
                        <span className="resource-planner-item__sub text-muted">
                          {viewMode === "WORK_ITEMS"
                            ? [row.projectName, row.taskName, row.dominantStatus].filter(Boolean).join(" · ")
                            : viewMode === "PROJECTS"
                              ? `${row.items.length} task item(s)${row.dominantStatus ? ` · ${row.dominantStatus}` : ""}`
                              : [row.projectName || row.taskName, row.dominantStatus].filter(Boolean).join(" · ")}
                        </span>
                      </span>
                      <span className="resource-planner-item__duration">{formatHours(row.minutes)}</span>
                    </button>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {typeof document !== "undefined" &&
        createPortal(
          <CreateWorkItemSidebar
            employees={props.employees}
            show={props.showTaskPlannerCreateModel}
            closeActionHandler={closeCreateItem}
            permission={permission}
            label="Resource Planner"
            defaultSelectedStatusOption={"ASSIGNED"}
            createButtonLabel={"Assign Tasks"}
            handleReloadWorkItems={refreshAfterSave}
            minDate={
              weekStartMoment &&
              workItemUtils.getWorkItemCreateStartMinDate(weekStartMoment.clone(), permission)
            }
            maxDate={
              weekStartMoment &&
              workItemUtils.getWorkItemCreateEndMaxDate(
                getCurrentRange().endDateMoment.clone(),
                permission
              )
            }
          />,
          document.body
        )}
    </div>
  );
}

const mapStateToProps = (state) => ({
  isLoading: state.workItem.isLoadingCompleted,
  workItems: state.workItem.workItems,
  employees: state.employees.teamEmployees,
  userTeamsTaskPlanner: state.workItem.userTeamsTaskPlanner,
  userTeams: state.authentication.userTeams,
  showTaskPlannerCreateModel: state.workItem.showTaskPlannerCreateModel,
});

const mapDispatchToProps = {
  getTeamsEmployees: employeeActions.getTeamsEmployees,
  getWorkItemActivities: workItemActions.getWorkItemActivities,
};

export default withRouter(connect(mapStateToProps, mapDispatchToProps)(ResourcePlanner));