import React, { Component } from 'react';
import { Link } from 'react-router-dom';
import BrandNameLogo from 'views/common/fragments/BrandNameLogo';
import { userActions } from '_actions';
import { connect } from 'react-redux';
import PropTypes from "prop-types";
import { store } from '_helpers';
import { validationUtils } from "_helpers";
import LoginPageFooter from './LoginPageFooter';

import { MicrosoftLoginSection } from './components/MicrosoftLoginSection';
import { userUtils } from '_helpers';

class LoginPage extends Component {
  constructor() {
    super();
    this.state = {
      passwordType: 'password',
      submitted: false,
      email: "",
      password: "",
      errors: {
        email: "",
        password: ""
      }
    };
  }

  togglePasswordType = () => {
    this.setState({
      passwordType: this.state.passwordType === 'text' ? 'password' : 'text'
    })
  }

  onSubmit = (e) => {
    e.preventDefault();
    this.setState({ invalidEmail: false });
    this.setState({ submitted: true });
    if (this.state.email && validationUtils.validateEmail(this.state.email)) {
      if (this.state.password) {
        store.dispatch(this.props.login(this.state.email, this.state.password, "FS"), null);
      }
    } else {
      this.setState({ invalidEmail: true });
    }
  }

  onChange = (e) => {
    this.setState({ submitted: false });
    const { name, value } = e.target;
    this.setState({ [name]: value });
  }

  render() {
    const appLoginEnabled = userUtils.getLoginType() === 'FS';
    return (
      <div className="auth-login">
        <div className="auth-login__shell">
          <div className="card auth-login__card">
            <BrandNameLogo />

            <div className="card-body">
              <div className="card-title auth-login__title">Login to your account</div>
              {this.props.authentication.error && (
                <div className="auth-login__alert alert alert-danger" role="alert">
                  {this.props.authentication.errorMessage}
                </div>
              )}
              <fieldset className="disabled" disabled={!appLoginEnabled}>
                <div className="form-group">
                  <label className="form-label">Email</label>

                  <div className="input-icon">
                    <span className="input-icon-addon"><i className="fe fe-user"></i></span>
                    <input type="email" className="form-control" id="inputEmail"
                      placeholder="Email Address"
                      name="email"
                      value={this.state.email} onChange={this.onChange}
                    />
                  </div>
                  {this.state.submitted && !this.state.email &&
                    <div className="invalid-feedback">Email is required</div>
                  }
                </div>
                <div className="form-group">
                  <label className="form-label">Password
                    {appLoginEnabled &&
                      <Link to={"/user/forgotpassword"} className="float-right" data-ga-action="click_forgot_password" data-ga-category="auth" data-ga-label="Login page">I forgot password</Link>
                    }
                  </label>

                  <div className="passwordinputcontainer">
                    <span className="input-icon-addon"><i className="fe fe-lock"></i></span>
                    <input type={this.state.passwordType} className="form-control passwordinput" id="exampleInputPassword1"
                      placeholder="Password"
                      name="password"
                      value={this.state.password} onChange={this.onChange}
                    />
                    <button
                      type="button"
                      className="passwordshoweye"
                      onClick={this.togglePasswordType}
                      aria-label={this.state.passwordType === 'text' ? 'Hide password' : 'Show password'}
                    >
                      <i className={`fe ${this.state.passwordType === 'text' ? 'fe-eye-off' : 'fe-eye'}`} aria-hidden="true" />
                    </button>
                  </div>

                  {this.state.submitted && !this.state.password &&
                    <div className="invalid-feedback">Password is required</div>
                  }
                </div>
                <div className="form-group">
                  <label className="custom-control custom-checkbox">
                    <input type="checkbox" className="custom-control-input" />
                    <span className="custom-control-label">Remember me</span>
                  </label>
                </div>
              </fieldset>
              <div className="form-footer">
                <fieldset className="disabled" disabled={!appLoginEnabled}>
                  <button className="btn btn-primary btn-block" onClick={this.onSubmit} data-ga-action="login_submit" data-ga-category="auth" data-ga-label="Sign in">
                    {this.props.authentication.loggingIn && <span className="spinner-border spinner-border-sm mr-1"></span>}
                    Sign in
                  </button>
                </fieldset>
                <span className="auth-login__or" aria-hidden="true">
                  or
                </span>
                <span className='d-block text-center'>
                  <MicrosoftLoginSection />
                </span>
              </div>
            </div>

            <div className="text-center text-muted d-none">
              Don't have account yet? <Link to={"/user/login"} data-ga-action="login_sign_up" data-ga-category="auth" data-ga-label="Sign up">Sign up</Link>
            </div>
            <LoginPageFooter />
          </div>
        </div>
      </div>
    );
  }
}

LoginPage.propTypes = {
  login: PropTypes.func.isRequired,
  authentication: PropTypes.object.isRequired
};

const mapStateToProps = state => ({
  authentication: state.authentication,
});

const mapDispatchToProps = dispatch => ({
  login: userActions.login
});

export default connect(
  mapStateToProps,
  mapDispatchToProps
)(LoginPage);


