import React, { Component } from "react";
import { userUtils } from "_helpers";
import { accessUtils } from "_helpers";
import DeviceRegistrationPopup from "./DeviceRegistrationPopup";
import "./MobileRegistrationMenu.css";

class MobileRegistrationMenu extends Component {
  constructor() {
    super();
    this.state = {
      isPopupOpen: false,
      shouldShow: false
    };
  }

  componentDidMount() {
    this.checkShouldShow();
  }

  checkShouldShow = () => {
    const permission = accessUtils.getProfileSettingsControl();
    const user = userUtils.getCurrentUser();
    
    const deviceRegistrationEnabled = permission && permission.deviceRegistrationEnabled === true;
    const deviceAppEnabled = user && user.deviceAppEnabled === true;
    const hasNoDeviceId = user && user.deviceRegistered === false;
    
    const shouldShow = deviceRegistrationEnabled && deviceAppEnabled && hasNoDeviceId;
    
    this.setState({ shouldShow });
  }

  handleIconClick = () => {
    this.setState({ isPopupOpen: true });
    // Add body class to disable page interactions
    document.body.classList.add('device-registration-popup-open');
  }

  handleClosePopup = (e) => {
    if (e) {
      e.preventDefault();
      e.stopPropagation();
    }
    
    // Close popup immediately
    this.setState({ isPopupOpen: false });
    
    // Remove body class to re-enable page interactions
    document.body.classList.remove('device-registration-popup-open');
    
    // Re-check if menu should still be shown after closing
    setTimeout(() => {
      this.checkShouldShow();
    }, 0);
  }

  componentWillUnmount() {
    // Clean up body class if component unmounts while popup is open
    document.body.classList.remove('device-registration-popup-open');
  }

  render() {
    if (!this.state.shouldShow) {
      return null;
    }

    return (
      <>
        <div 
          className="mobile-registration-icon-container"
          onClick={this.handleIconClick}
          title="Mobile App Registration"
        >
          <div className="mobile-phone-shape">
            <div className="qr-code-badge">
              <i className="fa fa-qrcode"></i>
            </div>
            <div className="registration-indicator">REG</div>
            <i className="fa fa-mobile-alt mobile-phone-icon"></i>
            <div className="home-button"></div>
          </div>
        </div>
        {this.state.isPopupOpen && (
          <DeviceRegistrationPopup 
            onClose={this.handleClosePopup}
            onRegistrationComplete={this.checkShouldShow}
          />
        )}
      </>
    );
  }
}

export default MobileRegistrationMenu;
