import React, { PureComponent } from "react";
import { connect } from "react-redux";
import PageInnerHeader from "views/common/PageInnerHeader";
import { accessUtils } from "_helpers";
import { store } from "_helpers";
import { commonUtils } from "_helpers";
import dateUtils from "_helpers/date.utils";
import { taskService } from "_services";
import { projectConstants } from "_constants";
import { employeeActions } from "_actions";
import { notificationActions } from "_actions";
import ItemNotFoundSection from "./components/ItemsNotFoundSection";
import NotesStickyBoard from "./components/NotesStickyBoard";
import NotesListTable from "./components/NotesListTable";
import NoteEditorModal from "./components/modal/NoteEditorModal";
import originalMoment from "moment";
import { extendMoment } from "moment-range";

const moment = extendMoment(originalMoment);

function parseNoteDateTime(value) {
  if (!value) {
    return null;
  }
  if (typeof value === "string") {
    const m = dateUtils.convertDateStringToMoment(value);
    return m && m.isValid() ? m : null;
  }
  if (Array.isArray(value) && value.length >= 5) {
    const [y, mo, d, h, mi] = value;
    return moment({ year: y, month: (mo || 1) - 1, day: d || 1, hour: h || 0, minute: mi || 0 });
  }
  return null;
}

function formatNoteWhen(value) {
  const m = parseNoteDateTime(value);
  return m ? m.format("YYYY-MMM-DD HH:mm") : "—";
}

function mergePermission() {
  const projectPerm = accessUtils.getProjectAccessControl();
  const taskBoardPerm = accessUtils.getTaskBoardAccessControl();
  return {
    createEnabled: projectPerm.createEnabled,
    editEnabled: projectPerm.editEnabled,
    removeEnabled: projectPerm.removeEnabled,
    switchUserTeamsEnabled: projectPerm.switchUserTeamsEnabled,
    switchEmployeesEnabled: taskBoardPerm.switchEmployeesEnabled === true,
  };
}

class ToDoListPage extends PureComponent {
  constructor() {
    super();
    const permission = mergePermission();
    this.state = {
      permission,
      items: [],
      isLoading: false,
      selectedEmployeeId: commonUtils.getCurrentUserId(),
      filterOptions: {
        filterText: "",
        dateRangeValue: dateUtils.getDefaultDateRange(),
      },
      showNoteModal: false,
      editingNote: null,
      isSavingNote: false,
      /** Same pattern as project list: `true` = board (sticky notes), `false` = table. */
      showGrid: true,
    };
  }

  onGridClick = (e) => {
    e.preventDefault();
    this.setState({ showGrid: true });
  };

  onListClick = (e) => {
    e.preventDefault();
    this.setState({ showGrid: false });
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
    this.bootstrapTeamsAndEmployees();
    this.loadNotes();
  }

  componentDidUpdate(prevProps) {
    const hadTeams = prevProps.userTeams && prevProps.userTeams.length;
    const hasTeams = this.props.userTeams && this.props.userTeams.length;
    if (!hadTeams && hasTeams) {
      this.bootstrapTeamsAndEmployees();
    }
  }

  bootstrapTeamsAndEmployees = () => {
    const userTeams = commonUtils.getUserTeams(this.props.userTeams);
    if (!userTeams || !userTeams.length) {
      return;
    }
    store.dispatch({ type: projectConstants.INITIALIZE_PROJECTS_USER_TEAMS, userTeams });
    if (this.state.permission.switchEmployeesEnabled && this.props.getTeamsEmployees) {
      let teamIds = commonUtils.getSelectedUserTeamIds(userTeams);
      if (!teamIds || teamIds.length === 0) {
        const t = commonUtils.getCurrentUserTeamId();
        teamIds = t ? [t] : [];
      }
      if (teamIds.length) {
        store.dispatch(this.props.getTeamsEmployees(teamIds));
      }
    }
  };

  getNotesEmployeeId = () => {
    if (this.state.permission.switchEmployeesEnabled && this.state.selectedEmployeeId) {
      return this.state.selectedEmployeeId;
    }
    return commonUtils.getCurrentUserId();
  };

  loadNotes = () => {
    const employeeId = this.getNotesEmployeeId();
    if (!employeeId) {
      return;
    }
    const start = this.state.filterOptions.dateRangeValue.start.clone().startOf("day").format(dateUtils.SERVER_DATE_FORMAT);
    const end = this.state.filterOptions.dateRangeValue.end.clone().endOf("day").format(dateUtils.SERVER_DATE_FORMAT);
    this.setState({ isLoading: true });
    taskService
      .listNotes({
        employeeId,
        currentEmployeeId: commonUtils.getCurrentUserId(),
        startDate: start,
        endDate: end,
      })
      .then((res) => {
        const raw = res && res.payload;
        const items = Array.isArray(raw) ? raw : raw ? [raw] : [];
        this.setState({ items, isLoading: false });
      })
      .catch(() => {
        this.setState({ items: [], isLoading: false });
      });
  };

  onFilterTextChange = (value) => {
    this.setState((prev) => ({
      filterOptions: { ...prev.filterOptions, filterText: value },
    }));
  };

  handleDateRangeChange = (range) => {
    this.setState(
      (prev) => ({
        filterOptions: { ...prev.filterOptions, dateRangeValue: range },
      }),
      () => this.loadNotes()
    );
  };

  handleUserTeamsSelection = (userTeams) => {
    store.dispatch({ type: projectConstants.INITIALIZE_PROJECTS_USER_TEAMS, userTeams });
    if (this.state.permission.switchEmployeesEnabled && this.props.getTeamsEmployees) {
      let teamIds = commonUtils.getSelectedUserTeamIds(userTeams);
      if (!teamIds || teamIds.length === 0) {
        const t = commonUtils.getCurrentUserTeamId();
        teamIds = t ? [t] : [];
      }
      if (teamIds.length) {
        store.dispatch(this.props.getTeamsEmployees(teamIds));
      }
    }
    this.loadNotes();
  };

  handleEmployeesSelection = (employees) => {
    const ids = commonUtils.getSelectedEmployeeIds(employees);
    const id = ids && ids.length ? ids[0] : commonUtils.getCurrentUserId();
    this.setState({ selectedEmployeeId: id }, () => this.loadNotes());
  };

  onCreateItemClick = () => {
    this.setState({ showNoteModal: true, editingNote: null });
  };

  closeNoteModal = () => {
    if (!this.state.isSavingNote) {
      this.setState({ showNoteModal: false, editingNote: null });
    }
  };

  saveNote = (payload) => {
    this.setState({ isSavingNote: true });
    const isEdit = !!(this.state.editingNote && this.state.editingNote.id);
    const req = isEdit ? taskService.updateNote(payload) : taskService.createNote(payload);
    req
      .then(() => {
        store.dispatch(notificationActions.success(isEdit ? "Note updated" : "Note created"));
        this.setState({ isSavingNote: false, showNoteModal: false, editingNote: null });
        this.loadNotes();
      })
      .catch((err) => {
        const msg = (err && err.message) || err || "Could not save note";
        store.dispatch(notificationActions.error(String(msg)));
        this.setState({ isSavingNote: false });
      });
  };

  openEdit = (note) => {
    this.setState({ showNoteModal: true, editingNote: note });
  };

  toggleComplete = (note) => {
    const next = note.status === "COMPLETED" ? "IN_PROGRESS" : "COMPLETED";
    taskService
      .updateNoteStatus(note.id, next)
      .then(() => {
        this.loadNotes();
      })
      .catch((err) => {
        store.dispatch(notificationActions.error(String((err && err.message) || err || "Update failed")));
      });
  };

  deleteNote = (note) => {
    if (!window.confirm("Delete this note?")) {
      return;
    }
    taskService
      .removeNote(note.id)
      .then(() => {
        store.dispatch(notificationActions.success("Note deleted"));
        this.loadNotes();
      })
      .catch((err) => {
        store.dispatch(notificationActions.error(String((err && err.message) || err || "Delete failed")));
      });
  };

  filteredItems = () => {
    const q = (this.state.filterOptions.filterText || "").trim().toLowerCase();
    if (!q) {
      return this.state.items;
    }
    return this.state.items.filter((n) => {
      const name = (n.name || "").toLowerCase();
      const desc = (n.description || "").toLowerCase();
      return name.includes(q) || desc.includes(q);
    });
  };

  render() {
    const userTeams = commonUtils.getUserTeams(this.props.userTeams);
    const employees = this.props.employees || [];
    const rows = this.filteredItems();
    const canUseEmployees =
      this.state.permission.switchEmployeesEnabled === true && employees.length > 0;

    return (
      <div className="projectlist">
        <PageInnerHeader
          showCreateMenu={this.state.permission.createEnabled}
          showGridListMenu={true}
          showGridDefault={this.state.showGrid}
          gridClickHandler={this.onGridClick}
          listClickHandler={this.onListClick}
          searchViewEnabled={false}
          showFilter={true}
          showUserTeamMenu={this.state.permission.switchUserTeamsEnabled === true}
          userTeams={userTeams}
          handleUserTeamsSelection={this.handleUserTeamsSelection}
          showEmployeeMenu={canUseEmployees}
          employees={employees}
          handleEmployeesSelection={this.handleEmployeesSelection}
          enableUserTeamSingleSelection
          showEmployeeNameDropDownLabel
          applyEmployeeSelectionImmediately
          isLoading={this.state.isLoading}
          onFilterTextChange={this.onFilterTextChange}
          showCreateMenuText="Add note"
          createItemHandler={this.onCreateItemClick}
          showDateRangeSelector
          filterOptions={this.state.filterOptions}
          handleDateRangeChange={this.handleDateRangeChange}
          handleFilterChange={() => {}}
        />
        {(rows.length > 0 || this.state.isLoading) && (
          <div className="section-body mt-1">
            <div className="container-fluid">
              <div className="row">
                <div className="col-lg-12">
                  <div className="tab-content">
                    {this.state.showGrid && (
                      <NotesStickyBoard
                        items={rows}
                        isLoading={this.state.isLoading}
                        permission={this.state.permission}
                        formatWhen={formatNoteWhen}
                        onToggleComplete={this.toggleComplete}
                        onEdit={this.openEdit}
                        onDelete={this.deleteNote}
                      />
                    )}
                    {!this.state.showGrid && (
                      <NotesListTable
                        items={rows}
                        isLoading={this.state.isLoading}
                        permission={this.state.permission}
                        formatWhen={formatNoteWhen}
                        onToggleComplete={this.toggleComplete}
                        onEdit={this.openEdit}
                        onDelete={this.deleteNote}
                      />
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        <ItemNotFoundSection
          items={rows}
          isLoading={this.state.isLoading}
          imgurl="noactivetasks-min.PNG"
          text="No notes in this range"
          description="Add a note or widen the date range."
          bgcolor="bgcolorwhite"
        />

        <NoteEditorModal
          show={this.state.showNoteModal}
          note={this.state.editingNote}
          onClose={this.closeNoteModal}
          onSave={this.saveNote}
          isSaving={this.state.isSavingNote}
        />
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  userTeams: commonUtils.getUserTeams(state.projects.userTeams),
  employees: state.employees.teamEmployees && commonUtils.getActiveEmployees(state.employees.teamEmployees),
});

const mapDispatchToProps = (dispatch) => ({
  getTeamsEmployees: employeeActions.getTeamsEmployees,
});

export default connect(mapStateToProps, mapDispatchToProps)(ToDoListPage);
